// FLUXO 04 - Registrar recebimento fisico no RIO
// Registra o horario da DETECCAO pelo n8n (UTC), nao o instante exato do clique.
// Para notas confirmadas antes de ativar este fluxo, nao representa a data historica real.
const paginas = $input.all();
const agora = new Date().toISOString();
const base = 'https://graph.microsoft.com/v1.0/sites/somagrupo.sharepoint.com,075fb68d-54fc-4858-b09d-af763d92b964,3c8776be-edcf-4010-91eb-5aecfe30eb0d/lists/1f2c46e7-91ba-4edf-96a4-78c8124ba125';
const saida = [];
const vistos = new Set();

for (const pagina of paginas) {
  const itens = Array.isArray(pagina.json.value) ? pagina.json.value : [];
  for (const item of itens) {
    const id = String(item.id ?? '').trim();
    const f = item.fields || {};
    const recebido = f.RECEBIMENTO_RIO === true || f.RECEBIMENTO_RIO === 1 ||
      String(f.RECEBIMENTO_RIO ?? '').toLowerCase() === 'true' ||
      String(f.RECEBIMENTO_RIO ?? '') === '1';
    const temData = f.DATA_RECEBIMENTO_RIO != null && String(f.DATA_RECEBIMENTO_RIO).trim() !== '';
    if (!id || !recebido || temData || vistos.has(id)) continue;
    vistos.add(id);
    saida.push({json: {
      item_id: id,
      identificacao: String(f.Title ?? '').trim(),
      data_recebimento_rio: agora,
      url_sharepoint: `${base}/items/${encodeURIComponent(id)}/fields`
    }});
  }
}
return saida;
